fields.InputDefinition:
{
  "goal": "Open the 'Events' entity grid — type 'Events' in the LEFT sidebar 'Search entities...' box and click the exact 'Events' node (or, if the search is giving you trouble, navigate directly to http://localhost:4200/app/data-explorer/Data?entity=Events). Click a row, then click 'Open Full Record'. In the record toolbar (the row of icons at the TOP-LEFT, just above the Details card), click the 'Add to a list' control — the BOOKMARK icon. Verify a dialog/panel opens for adding the record to a List (it shows list options to pick from, or a create-list / select-list UI), with no error. You do NOT need to finish adding — opening the dialog is success. Pages can take 10-30s to load — wait, don't navigate away.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "minConfidence": 0.7,
  "maxSteps": 35,
  "judgeValidationCriteria": [
    "The 'Add to a list' (bookmark icon) control in the record toolbar was clicked",
    "A dialog/panel for adding the record to a List opened (list selection or create-list UI)",
    "No error messages or crash pages"
  ]
}
